templates.globals:
static string up_(string s) { for (auto &c : s) c = toupper((unsigned char)c); return s; }
static bool has_(const string &s, initializer_list<const char*> ws) { for (auto w : ws) if (s.find(w) != string::npos) return true; return false; }
// operacja bez argumentu: zapytanie (podgląd/rozmiar) czy zdjęcie elementu?
static bool is_peek_(const string &op) { return has_(up_(op), {"TOP", "FRONT", "PEEK", "SZCZYT", "GORA", "WIERZCH", "PIERWSZ", "PODAJ", "JAKI", "KTO", "POKAZ", "SPRAWDZ"}); }
static bool is_size_(const string &op) { return has_(up_(op), {"SIZE", "ILE", "ROZMIAR", "LICZB", "DLUGOSC", "COUNT"}); }

templates.solve:
ll q; cin >> q; string line; getline(cin, line);
deque<string> c;
for (ll i = 0; i < q && getline(cin, line); i++) {
    stringstream ss(line); string op, arg; ss >> op; if (op.empty()) { i--; continue; }
    if (ss >> arg) c.push_back(arg);                                  // operacja z argumentem: dodaj
    else if (is_size_(op)) cout << c.size() << "\n";
    else if (is_peek_(op)) { if (c.empty()) cout << "{{NONE}}" << "\n"; else cout << c.front() << "\n"; }
    else { if (c.empty()) cout << "{{NONE}}" << "\n"; else { cout << c.front() << "\n"; c.pop_front(); } }
}

